mapper.select:
  select  ROW_NUMBER() over (order by resource_no ) as no,resource_no ,resource_type,resource_name,resource_status,resource_org_size ,resource_new_size_type2 from om_cloud_optimizer_tbl ocot 
  where 1=1 
  and resource_type > 0 
  and resource_org_size >0


	     	  AND 5 > resource_type 


	     	  AND resource_type > 4 


		and resource_type = #{resource_type}


		and resource_status = #{resource_status}


		and  1  > resource_status 


        AND site_no IN

            CAST(#{item} AS INTEGER)






					ORDER BY resource_type ${sortItem.dir} 


					ORDER BY  resource_name ${sortItem.dir} 


					ORDER BY  resource_status ${sortItem.dir} 


					ORDER BY  resource_org_size  ${sortItem.dir} 


					ORDER BY  resource_new_size_type2 ${sortItem.dir} 






		LIMIT #{size} OFFSET #{offset}
